-- D-22 Food Defense + Food Fraud, all DRAFT:
--   FSQM-025 Food Defense Plan
--   FSQM-026 Food Fraud Vulnerability Assessment and Mitigation Plan
--   FRM-014  Food Defense and Food Fraud Review and Test Record
--
-- Eight Minor findings: 2.7.1.1-.4 and 2.7.2.1-.4. FSQM-025/026 are reserved in the remediation workbook;
-- FRM-014 is the next free FRM-0xx number. Nothing existed before: no threat assessment, no food defense
-- plan, no vulnerability assessment, no mitigation plan. TRN-011 (active) already teaches both subjects.
--
-- Owner's answers, 2026-10-02: outside doors locked when the site is empty, keys with named people, NOT
-- locked during working hours; cameras, no alarm; staff presence on the timesheet; the rum is supplied by
-- the customer; the label states "contains less than 4% alcohol". Materials from the product's ingredient
-- statement (which declares pecans) and FRM-207.
-- The assessments are bullets with sub-items in the document body, as FSQM-016 Part 7 is. One record,
-- FRM-014, serves the yearly review of both plans and the food defense test (2.7.1.4, 2.7.2.4), and carries
-- the NAME 2.7.1.2 ii asks for - the controlled documents name positions only.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-025', 'FSQM-026', 'FRM-014')) then
    raise exception 'a D-22 document number is already in use.';
  end if;
  if (select count(distinct sop_number) from public.sop_documents
       where sop_number in ('FSQM-004', 'FSQM-009', 'FSQM-012', 'FSQM-018', 'FSQM-023', 'FSQM-032', 'FSQM-035', 'FSQM-036', 'FSQM-037', 'SOP-2.2.3', 'SOP-2.3.2', 'SOP-2.3.4', 'TRN-011', 'FRM-007', 'FRM-011', 'FRM-202', 'FRM-207', 'FRM-301', 'FRM-520', 'FRM-601', 'FRM-701', 'FRM-702', 'FRM-801', 'FRM-905') and status in ('active', 'draft')) <> 24 then
    raise exception 'a document D-22 names is missing: %', (
      select string_agg(n, ', ') from unnest(array['FSQM-004', 'FSQM-009', 'FSQM-012', 'FSQM-018', 'FSQM-023', 'FSQM-032', 'FSQM-035', 'FSQM-036', 'FSQM-037', 'SOP-2.2.3', 'SOP-2.3.2', 'SOP-2.3.4', 'TRN-011', 'FRM-007', 'FRM-011', 'FRM-202', 'FRM-207', 'FRM-301', 'FRM-520', 'FRM-601', 'FRM-701', 'FRM-702', 'FRM-801', 'FRM-905']) n
       where not exists (select 1 from public.sop_documents d where d.sop_number = n and d.status in ('active', 'draft')));
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-025', 'Food Defense Plan', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.7.1.1, 2.7.1.2, 2.7.1.3, 2.7.1.4', true, $q${"purpose": "This plan states how Adventure Bakery prevents somebody deliberately contaminating its product: the threats it has assessed, who may enter the site, how the open product is protected, and how the plan is tested each year.", "scope": "Both units, everything stored in them, and every person who enters: staff, visitors, contractors and collecting drivers. Fraud for money - a material that is not what it claims to be - is covered by FSQM-026.", "definitions": "Food defense: protecting food from deliberate contamination meant to cause harm.\nTampering: any sign that a material, product, container or piece of equipment has been deliberately interfered with.\nSensitive point: a place where product or an ingredient is open and one act could contaminate a whole batch.\nThreat level: how likely a deliberate act is judged to be. It is set in the threat assessment.", "responsibility": "Senior Site Management - the senior site manager responsible for food defense; holds the list of key holders, decides what is done when tampering is suspected, and arranges the yearly test.\nSQF Practitioner - carries out the threat assessment, keeps this plan current and records the review and test on FRM-014. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nAll staff - stop and ask anyone they do not know, keep visitors with them, lock up, and report anything that looks tampered with.", "procedure": ["The threat assessment", "• The SQF Practitioner assesses, with Senior Site Management, how somebody could deliberately contaminate product on this site, how likely it is, and what stops it (SQF 2.7.1.1). The result is below.", "• The site: two units in a light industrial complex, with warehousing and light industry as neighbours. A small team that knows each other. Every product is collected by the customer; the site runs no delivery vehicles. Product is vacuum sealed and boxed before it leaves.", "• Who could do it, and how likely:", "◦ Somebody walking in during working hours - the main threat. The entrance is not locked while the team is working, and the team may all be in the production room. Control: a chime sounds in reception and in the production room whenever the entrance is opened, and a member of the team goes to meet whoever has come in; the entrance opens into the reception area only; two closed doors and an \"employees only\" sign stand between reception and production; anyone the team does not know is stopped and taken back to the sign-in screen; cameras record.", "◦ A break-in when the site is empty - unlikely. Every outside door is locked whenever nobody is there, keys are held by named people only, and cameras record. There is no intruder alarm. A break-in is treated as possible tampering (see \"If tampering is suspected\").", "◦ A visitor or contractor - unlikely. Each one signs in, and is with a member of the team in the production and storage rooms.", "◦ A member of the team - unlikely. Control: access ends when the job does - keys come back and the Team Portal account is closed the day a person leaves.", "◦ A collecting driver - unlikely. Drivers do not enter the production or storage rooms; product is brought out to the vehicle.", "◦ Material tampered with before it arrives - unlikely. Control: the receipt check on FRM-301.", "• Threat level: LOW. It is raised, and this assessment is done again, when any of these happens: a break-in or an attempt at the site or in the complex; a threat made against the site, its staff or a customer's brand; tampering found or suspected; a person leaving on bad terms; a warning from the FDA, the police or a customer.", "Who is responsible", "• Senior Site Management is the senior site manager responsible for food defense. The name of the person is written on every FRM-014 review record (SQF 2.7.1.2 ii).", "• Every member of the team stops and asks anyone they do not know, and reports anything that looks tampered with. Nobody is asked to confront a person who seems dangerous: leave, and call the police.", "Who can get in", "• Keys and door codes are held only by the people named on the latest FRM-014. The last person out checks that every outside door is locked.", "• Visitors and contractors come in through the entrance to the reception area, where the sign-in screen is. The entrance chime is heard in the production room, and a member of the team goes to reception when it sounds. Nobody but the team goes past the \"employees only\" sign and the two doors to production unless a member of the team takes them. Both doors are kept closed. The other outside doors are for staff, deliveries and collections, and are closed when not in use.", "• Only the team works in the production and storage rooms and on the equipment. A visitor or contractor is there only with a member of the team (FSQM-012 Part 6) (SQF 2.7.1.2 iii).", "The sensitive points", "• These are the places where product or an ingredient is open and one act could reach a whole batch (SQF 2.7.1.2 iv):", "◦ weighing and mixing - open ingredients and the mixer bowl;", "◦ the syrup - the kettle, and syrup kept for a later run;", "◦ baked product cooling on the racks, which can stand for hours and overnight;", "◦ dipping and packing, until the pouch is sealed.", "• Nobody but the team is at these points while product is open. Syrup that is kept is sealed and labelled. Product left to cool overnight is left in the locked building.", "• Before use, each container is looked at: an ingredient, a syrup container or a rack of product that is open, moved, or not as it was left is not used until Senior Site Management has seen it.", "Receiving and storing", "• A delivery is accepted only if it was expected, comes from an approved supplier (FRM-202) and its packs are sealed and undamaged; this is recorded on FRM-301. Deliveries are brought inside and are not left outside or unattended at the door (FSQM-035).", "• Cleaning chemicals are kept locked away from food and packaging (FSQM-032) (SQF 2.7.1.2 v).", "• Ingredients, packaging, labels, work in progress and finished product are all kept inside the locked building; nothing is stored outside. Printed packaging that is thrown away is defaced first (FSQM-037).", "• Transport: the collecting vehicle is checked and then secured by a lock or latch (FSQM-036, FRM-801). FSQM-036 named this assessment as the test of that rule. The assessment found no threat that the rule does not answer: the product is sealed, boxed and collected locally in small loads (SQF 2.7.1.2 vi).", "The record of who was on site", "• Staff: the timesheet shows who worked each day.", "• Visitors and contractors: each signs in and out on the entrance screen (FRM-905), which keeps the name, company, the person visited and the times (SQF 2.7.1.2 vii).", "If tampering is suspected", "• Stop. Do not use, move or throw away what was found. Tell Senior Site Management at once.", "• Everything that could have been reached is put on hold on FRM-702 under FSQM-018. After a break-in that means every open or unsealed ingredient, all syrup, and all product not yet sealed.", "• Senior Site Management decides what is disposed of, calls the police, and tells the FDA and the customer where product may be affected (the contacts are on FRM-011). If product has already left the site, FSQM-023 starts. A CAPA is raised on FRM-007 (SQF 2.7.1.2 i).", "Instruction", "• All staff complete the food defense and food fraud training module (TRN-011) in the Team Portal when they start and each year after. The Team Portal keeps the record (SQF 2.7.1.3).", "Review and test", "• At least once a year, and whenever the threat level is raised, the SQF Practitioner and Senior Site Management review the assessment and this plan, and test it. Both are recorded on FRM-014 (SQF 2.7.1.4).", "• The test: a person the team does not know, arranged by Senior Site Management, arrives without warning and tries to walk from reception into the production room. It passes if the person is stopped and taken back to the sign-in screen before passing the second door. At the same visit: every outside door is locked and tried, the key holders are checked against the list, the entrance chime is heard in the production room with the equipment running, and the cameras are confirmed to be recording.", "• A failed test or a gap is raised as a CAPA on FRM-007, and the result goes to the management review.", "Records", "• FRM-014 reviews and tests, FRM-905 visitor records, the timesheets, FRM-702 holds and FRM-007 CAPAs are kept as SOP-2.2.3 requires (SQF 2.7.1.4)."], "form_references": "FRM-014 - Food Defense and Food Fraud Review and Test Record\nFRM-905 - Visitor Sign-In Log\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-011 - Recall and Crisis Contact List\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-014 - one per yearly review and test, and one whenever the threat level is raised\n• FRM-905 visitor and contractor sign-in records\n• Staff timesheets\n• Training records for TRN-011 in the Team Portal", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.7.1.1, 2.7.1.2, 2.7.1.3, 2.7.1.4 (Food Defense Plan).\n\nFSQM-012 Good Manufacturing Practices Program - Part 6, visitors and contractors.\nFSQM-035 Receipt, Storage and Handling; FSQM-032 Chemical Control; FSQM-036 Loading, Transport and Unloading; FSQM-037 Waste Management.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-023 Product Withdrawal and Recall Program; FSQM-009 CAPA Program.\nFSQM-026 Food Fraud Vulnerability Assessment and Mitigation Plan.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.", "revision_history": "New - 2026-10-02 - DRAFT under D-22, for the Minor findings against 2.7.1.1 to 2.7.1.4. The site had no food defense plan and no threat assessment.\n\nOWNER'S ANSWERS (2026-10-02): every outside door is locked when the site is empty and keys are held by named people; the entrance is NOT kept locked during working hours; reception is separated from production by two doors and an \"employees only\" sign; there are cameras and no intruder alarm; staff presence is shown by the timesheet.\n\nTHE NAME: SQF 2.7.1.2 ii asks for the name of the responsible senior manager. Controlled documents here name positions, so the plan names Senior Site Management and the person's name is written on each FRM-014 record.\n\nFSQM-036 named this assessment as the review of its lock-or-latch rule for collecting vehicles. The rule stands.\n\nTRAINING: TRN-011 already covers food defense and food fraud for all staff. It is to be read against this plan before issue.\n\nAT ISSUE: add a yearly 'food defense and food fraud review and test' row to the verification schedule (FSQM-017 Part 6) against FRM-014.\n\nTO CONFIRM BEFORE ISSUE: (1) the entrance chime fitted, and heard in the production room with the mixer and the oven running - the owner chose a chime (2026-10-02) over locking the entrance or an inner door, and the plan is written as if it is in place; (2) how many other outside doors there are; (3) what the cameras cover and how long recordings are kept; (4) that chemicals are locked away (the FSQM-032 locker); (5) the first review and test recorded on FRM-014."}$q$::jsonb),
  ('FSQM-026', 'Food Fraud Vulnerability Assessment and Mitigation Plan', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.7.2.1, 2.7.2.2, 2.7.2.3, 2.7.2.4', true, $q${"purpose": "This plan states how Adventure Bakery finds where it could be the victim, or the source, of food fraud, and what it does to prevent it.", "scope": "Every ingredient and packaging material bought or supplied to the site, and every finished product and label. Deliberate contamination meant to cause harm is covered by FSQM-025.", "definitions": "Food fraud: deceiving a buyer about food for money.\nSubstitution: a cheaper material in place of the one declared.\nDilution: a material made to go further with something cheaper.\nMislabeling: a label that says something untrue about the product.\nCounterfeiting: a copy sold as the real brand.\nVulnerability: how open a material or product is to fraud.", "responsibility": "SQF Practitioner - carries out the vulnerability assessment, keeps this plan current, decides what is done with a suspect material, and records the yearly review on FRM-014. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nSenior Site Management - approves suppliers, materials and labels, and reviews the FRM-014 record.\nWhoever buys - buys only approved materials from approved suppliers.\nWhoever receives - checks each delivery on FRM-301 and holds anything that looks wrong.", "procedure": ["How the vulnerability is assessed", "• The SQF Practitioner assesses every ingredient and packaging material, and the finished product, for food fraud: substitution, dilution, mislabeling and counterfeiting (SQF 2.7.2.1).", "• It is done once a year, and before a new material, a new supplier or a new label claim is approved (FRM-207, FRM-202, FRM-601).", "• Three questions are asked of each material:", "◦ History - is this kind of material a known target for fraud?", "◦ Gain - could somebody make money by diluting it, swapping it or copying it, and would it be hard to see?", "◦ Route - does the way it reaches the site vouch for it? A sealed, branded pack from a recognized distributor does. An online marketplace or an unbranded pack does not.", "• Rating: LOW - not a known target, and the route vouches for it. MEDIUM - a known target, or a route that does not vouch for it. HIGH - both. A MEDIUM or HIGH material has a control of its own below.", "• For each material the assessment also asks what the fraud could do to food safety - above all, an allergen that is not on the label.", "The materials", "• Rum - MEDIUM. Spirits are a known target: counterfeit and watered-down product, and illicit spirit can contain methanol. The rum is supplied by the customer whose brand is on the pack.", "• Flavorings and colors bought from an online marketplace - MEDIUM. Flavorings are a known target, and a marketplace is where relabelled and counterfeit goods are sold.", "• Pecans - MEDIUM. Nuts are a known target: cheaper nuts mixed in, and old crop sold as new. A different nut is an allergen that is not on the label.", "• Soybean oil - LOW. Oils are a known target, but soybean oil is the cheapest common oil and there is nothing to gain by swapping it. It is bought as a sealed, branded pack.", "• Cake mix, sugar, liquid egg and pan release spray - LOW. Sealed, branded packs from recognized distributors; not known targets.", "• Packaging - film, pouches, boxes and labels - LOW. The fraud to guard against is somebody else using a customer's printed packaging; see \"The finished product\".", "The finished product", "• Mislabeling - the site packs under its customers' brands, so the label is the customer's statement and the site's act. What could be wrong: the ingredients or allergens, the statement \"contains less than 4% alcohol\", and the statement of who made the product and where.", "• Dilution or substitution - making the product with less rum, or with a cheaper material than the label declares.", "• Counterfeiting - another party selling product in a customer's packaging, or the site's product reaching anyone but the customer.", "The mitigation plan", "• Every material is bought only from a supplier approved on FRM-202, and only as the named product of the named manufacturer on FRM-207. A different brand is a new material: it is not used until it has been approved and its allergen statement checked (SOP-2.3.4, SOP-2.3.2).", "• Every delivery is checked on FRM-301: the brand and product match FRM-207, the pack is sealed, and it carries a lot code and a date. A pack that fails is not used; it is held on FRM-702.", "• Rum: accepted only in the supplier's sealed, labelled containers, as the product the customer specifies, and recorded on FRM-301 with its lot or bottling code. Rum that arrives unsealed or unlabelled is not used and the customer is told.", "• Online marketplace: used only for the materials and under the conditions written on that supplier's FRM-202 - sold by the marketplace itself or the brand's own store, the exact brand on FRM-207, seal and lot checked, the order number written on FRM-301. Where a distributor or the manufacturer can supply the material, it is bought there.", "• Pecans: bought as a sealed, branded pack that declares pecans only, from an approved supplier; the allergen statement on the pack is read at receipt.", "• Signs that are acted on: a price well below the usual, a new seller, a pack or label that looks different, a broken seal, a missing lot code, a material that looks, smells or behaves differently. The material is held on FRM-702 and the SQF Practitioner decides.", "• The label: every label is approved on FRM-601 before use and checked against the approved label at release on FRM-701. A statement on a label - the alcohol content, who made the product and where - is approved only when the site holds the basis for it.", "• The recipe: ingredients are weighed to the recipe and recorded on FRM-520, so the product is made with what the label declares. A change of material or recipe goes through SOP-2.3.2 and a label check before it is used.", "• The packaging: customers' printed packaging is kept inside the locked building and defaced before it is thrown away (FSQM-037). Finished product is released only to the customer or the carrier it sends (FRM-801) (SQF 2.7.2.2).", "Instruction", "• All staff complete the food defense and food fraud training module (TRN-011) in the Team Portal. Whoever buys or receives materials is also shown this plan and the signs above (SQF 2.7.2.3).", "Review and verification", "• At least once a year the SQF Practitioner reviews this assessment and verifies that the plan is being followed, recorded on FRM-014 (SQF 2.7.2.4):", "◦ every material in use is on FRM-207 and is rated here;", "◦ every supplier used is approved on FRM-202;", "◦ recent FRM-301 receipts are checked against FRM-207 - brand, seal and lot;", "◦ recalls, supplier notices and fraud alerts for these materials are looked at;", "◦ the label statements are still true of the product.", "• Gaps and the corrective actions are written on FRM-014, and a CAPA is raised on FRM-007 where one is needed.", "Records", "• FRM-014 reviews, FRM-202, FRM-207, FRM-301, FRM-601 and FRM-007 are kept as SOP-2.2.3 requires (SQF 2.7.2.4)."], "form_references": "FRM-014 - Food Defense and Food Fraud Review and Test Record\nFRM-202 - Supplier Approval & Evaluation Record\nFRM-207 - Material Specification Register\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-520 - Production Lot Record\nFRM-601 - label approval\nFRM-701 - Finished Product Release Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-014 - one per yearly review, and one when a material, supplier or claim is added\n• FRM-202 supplier approvals and FRM-207 material specifications\n• FRM-301 receipts\n• Training records for TRN-011 in the Team Portal", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.7.2.1, 2.7.2.2, 2.7.2.3, 2.7.2.4 (Food Fraud).\n\nSOP-2.3.4 Vendor Approval; SOP-2.3.2 specification control.\nFSQM-018 Non-Conforming Product and Equipment; FSQM-009 CAPA Program; FSQM-037 Waste Management.\nFSQM-025 Food Defense Plan.\nFSQM-004 Organizational Structure and Responsibilities - the positions named here.", "revision_history": "New - 2026-10-02 - DRAFT under D-22, for the Minor findings against 2.7.2.1 to 2.7.2.4. The site had no food fraud vulnerability assessment and no mitigation plan.\n\nOWNER'S ANSWERS (2026-10-02): the rum is supplied by the customer; the label carries the statement \"contains less than 4% alcohol\". The materials were taken from the product's ingredient statement and the FRM-207 register. The pack declares pecans (\"Original with pecans\"), so pecans are assessed here.\n\nTRAINING: TRN-011 already covers food defense and food fraud for all staff. It is to be read against this plan before issue.\n\nAT ISSUE: the yearly review is on the same verification schedule row as FSQM-025, against FRM-014.\n\nTO CONFIRM BEFORE ISSUE: (1) how the rum arrives - bottles or bulk, sealed, with a lot or bottling code - and that it is on FRM-207 and received on FRM-301; (2) where the pecans are bought, and their FRM-207 entry; (3) the basis for \"contains less than 4% alcohol\" - a calculation or a laboratory result, from the customer or held on site; (4) the box reads \"Manufactured by\" the brand owner at its own address, while this product is made at this site - the customer to confirm in writing that the statement is correct for product made here, or to correct it; (5) every material in use entered on FRM-207; (6) the first review recorded on FRM-014."}$q$::jsonb),
  ('FRM-014', 'Food Defense and Food Fraud Review and Test Record', 'form', 'Module 2', 'draft', 'New',
   '2.7.1.4, 2.7.2.4', true, jsonb_build_object('form_schema', $q${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{reason} - {date}"}, "sections": [{"id": "review", "title": "1. The review", "fields": [{"id": "how_this_works", "type": "info", "label": "How to use this", "text": "One record for each yearly review and test of the Food Defense Plan (FSQM-025) and the Food Fraud plan (FSQM-026), done together. Also use it when the threat level is raised, after an incident, or when a material, supplier or label claim is added - then mark the lines you did not look at \"Not reviewed this time\"."}, {"id": "reason", "type": "select", "label": "Reason", "width": "third", "required": true, "showInList": true, "options": ["Yearly review and test", "Threat level raised", "New material, supplier or claim", "After an incident"]}, {"id": "date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true}, {"id": "responsible_manager", "type": "text", "label": "Senior manager responsible for food defense", "width": "third", "required": true, "help": "The person's name (SQF 2.7.1.2 ii)"}, {"id": "taking_part", "type": "textarea", "label": "Who took part", "required": true, "help": "Names and positions"}]}, {"id": "defense", "title": "2. Food defense - review", "fields": [{"id": "defense_checks", "type": "grid", "label": "Food defense plan (FSQM-025)", "rowDialog": true, "columns": [{"id": "result", "label": "Result", "type": "select", "options": ["In place - no gap", "Gap found", "Not applicable", "Not reviewed this time"], "required": true, "width": 1}, {"id": "notes", "label": "What was looked at, and what was found", "type": "text", "width": 3, "scanFact": "none"}], "rows": {"mode": "fixed", "labels": ["The threats in FSQM-025 read through - they still match the site and its neighbours", "Since the last review: any break-in, threat, tampering or warning", "Every outside door locks, and was found locked when the site was empty", "Key and code holders match the list below; keys returned by anyone who left", "Visitors and contractors signed in and out on FRM-905 - recent entries looked at", "Timesheets kept for every working day", "Entrance chime working, and heard in the production room", "Cameras working and recording", "Chemicals locked away (FSQM-032)", "Deliveries checked on FRM-301 and not left outside", "Kept syrup and opened ingredients sealed and labelled", "Printed packaging kept inside; waste defaced (FSQM-037)", "TRN-011 completed by every member of staff"], "labelHeader": "Checked"}}, {"id": "key_holders", "type": "textarea", "label": "Key and code holders", "required": true, "help": "The name of every person who holds a key or a door code today"}, {"id": "threat_level", "type": "select", "label": "Threat level", "width": "third", "required": true, "showInList": true, "options": ["Low - unchanged", "Raised"]}, {"id": "threat_notes", "type": "textarea", "label": "If raised: why, and what has changed in the plan"}]}, {"id": "test", "title": "3. Food defense - test", "description": "The yearly test: a person the team does not know arrives without warning and tries to walk from reception into the production room.", "fields": [{"id": "test_result", "type": "select", "label": "Result", "width": "half", "required": true, "options": ["Passed - stopped before the second door", "Failed - CAPA raised", "Not tested - this is not the yearly review"]}, {"id": "test_date", "type": "date", "label": "Date of the test", "width": "third"}, {"id": "test_scenario", "type": "textarea", "label": "What was tried, and what happened", "help": "Who came, which door, what time, who stopped them and where"}]}, {"id": "fraud", "title": "4. Food fraud - review and verification", "fields": [{"id": "fraud_checks", "type": "grid", "label": "Food fraud plan (FSQM-026)", "rowDialog": true, "columns": [{"id": "result", "label": "Result", "type": "select", "options": ["In place - no gap", "Gap found", "Not applicable", "Not reviewed this time"], "required": true, "width": 1}, {"id": "notes", "label": "What was looked at, and what was found", "type": "text", "width": 3, "scanFact": "none"}], "rows": {"mode": "fixed", "labels": ["Every material in use is on FRM-207 and is rated in FSQM-026", "Every supplier used since the last review is approved on FRM-202", "Recent FRM-301 receipts checked against FRM-207 - brand, seal and lot", "Rum received sealed and labelled, and recorded on FRM-301", "Online marketplace purchases - seller, seal and order number recorded on FRM-301", "Recalls, supplier notices and fraud alerts for our materials looked at", "Label statements still true of the product (FRM-601)", "Whoever buys and receives has been shown FSQM-026"], "labelHeader": "Checked"}}, {"id": "changes", "type": "textarea", "label": "Materials, suppliers or label claims added or changed since the last review", "help": "Write None if there were none. Each new one needs a rating in FSQM-026."}]}, {"id": "outcome", "title": "5. Gaps and actions", "fields": [{"id": "gaps", "type": "textarea", "label": "Gaps found, and the corrective action for each", "required": true, "help": "Write None if there were none"}, {"id": "capa_no", "type": "text", "label": "CAPA Report no. (FRM-007)", "width": "third"}]}, {"id": "sign", "title": "6. Sign-off", "fields": [{"id": "completed_by", "type": "signature", "label": "Reviewed by", "role": "filler", "required": true, "statement": "This is what was reviewed, tested and found."}, {"id": "approved_by", "type": "signature", "label": "Senior Site Management", "role": "verifier", "required": true, "statement": "I have reviewed this record; the plans are verified, or the gaps above are being acted on."}]}]}$q$::jsonb));

do $verify$
declare p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-025';
  if jsonb_array_length(p) <> 46 then raise exception 'FSQM-025 procedure is % lines, expected 46.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.7.1.1)', '2.7.1.2 i)', '2.7.1.2 ii)', '2.7.1.2 iii)', '2.7.1.2 iv)', '2.7.1.2 v)', '2.7.1.2 vi)', '2.7.1.2 vii)', '2.7.1.3)', '2.7.1.4)']) c where p::text like '%' || c || '%') <> 10 then
    raise exception 'FSQM-025 does not cite every limb of 2.7.1.';
  end if;
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-026';
  if jsonb_array_length(p) <> 42 then raise exception 'FSQM-026 procedure is % lines, expected 42.', jsonb_array_length(p); end if;
  if (select count(*) from unnest(array['2.7.2.1)', '2.7.2.2)', '2.7.2.3)', '2.7.2.4)']) c where p::text like '%' || c || '%') <> 4 then
    raise exception 'FSQM-026 does not cite every limb of 2.7.2.';
  end if;
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-025', 'FSQM-026', 'FRM-014')
              and content::text ~* 'Diana|Gabriela|Christina|GJM|Mercer|Pillsbury|Amazon|Sysco|Bahamas|Agilitant') then
    raise exception 'a D-22 document names a person, a supplier or a customer; controlled documents name positions.';
  end if;
  if (select count(*) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
                           jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-014') <> 18 then
    raise exception 'FRM-014 field count is wrong.';
  end if;
  if (select sum(jsonb_array_length(f->'rows'->'labels')) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
             jsonb_array_elements(s->'fields') f where d.sop_number = 'FRM-014' and f->>'type' = 'grid') <> 21 then
    raise exception 'FRM-014 does not carry its 21 review lines.';
  end if;
end $verify$;

commit;
